from __future__ import annotations

from typing import Any

import numpy as np
import scipy.sparse as sp
import tensorflow as tf


def scipy_to_sparse_tensor(matrix: sp.spmatrix) -> tf.SparseTensor:
    matrix = matrix.tocoo().astype(np.float32)
    indices = np.column_stack((matrix.row, matrix.col))
    sparse_tensor = tf.SparseTensor(
        indices=indices,
        values=matrix.data,
        dense_shape=matrix.shape,
    )
    return tf.sparse.reorder(sparse_tensor)


def convert_nested_to_keras(value: Any) -> Any:
    if sp.issparse(value):
        return scipy_to_sparse_tensor(value)
    if isinstance(value, np.matrix):
        return np.asarray(value)
    if isinstance(value, list):
        return [convert_nested_to_keras(item) for item in value]
    if isinstance(value, tuple):
        return tuple(convert_nested_to_keras(item) for item in value)
    if isinstance(value, dict):
        return {key: convert_nested_to_keras(item) for key, item in value.items()}
    return value


def ensure_dense_tensor(value: Any, dtype: tf.dtypes.DType = tf.float32) -> tf.Tensor:
    if sp.issparse(value):
        value = value.toarray()
    if isinstance(value, tf.SparseTensor):
        value = tf.sparse.to_dense(value)
    return tf.cast(tf.convert_to_tensor(value), dtype)


def ensure_index_tensor(value: Any) -> tf.Tensor:
    if sp.issparse(value):
        value = value.toarray()
    if isinstance(value, tf.SparseTensor):
        value = tf.sparse.to_dense(value)
    return tf.cast(tf.convert_to_tensor(value), tf.int32)


def adjacency_matmul(adjacency: Any, features: tf.Tensor) -> tf.Tensor:
    if sp.issparse(adjacency):
        adjacency = scipy_to_sparse_tensor(adjacency)
    if isinstance(adjacency, tf.SparseTensor):
        return tf.sparse.sparse_dense_matmul(adjacency, features)
    adjacency = ensure_dense_tensor(adjacency, dtype=features.dtype)
    return tf.linalg.matmul(adjacency, features)


def add_self_loops_dense(adjacency: tf.Tensor) -> tf.Tensor:
    adjacency = ensure_dense_tensor(adjacency)
    rank = adjacency.shape.rank
    if rank == 2:
        size = tf.shape(adjacency)[0]
        eye = tf.eye(size, dtype=adjacency.dtype)
    elif rank == 3:
        batch = tf.shape(adjacency)[0]
        size = tf.shape(adjacency)[1]
        eye = tf.eye(size, batch_shape=[batch], dtype=adjacency.dtype)
    else:
        raise ValueError("Adjacency tensor must be rank 2 or 3.")
    return tf.maximum(adjacency, eye)


class GraphInputMixin:
    """Converts SciPy sparse inputs for direct eager model/layer calls."""

    def __call__(self, *args: Any, **kwargs: Any) -> Any:
        converted_args = tuple(convert_nested_to_keras(arg) for arg in args)
        converted_kwargs = {key: convert_nested_to_keras(val) for key, val in kwargs.items()}
        return super().__call__(*converted_args, **converted_kwargs)


class FullBatchModel(GraphInputMixin, tf.keras.Model):
    """Keras model helper for full-graph training with 2D graph tensors."""

    def __init__(self, *args: Any, full_batch_training: bool = True, **kwargs: Any) -> None:
        super().__init__(*args, **kwargs)
        self.full_batch_training = full_batch_training

    def _infer_batch_size(self, x: Any) -> int | None:
        if isinstance(x, (list, tuple)):
            for item in x:
                inferred = self._infer_batch_size(item)
                if inferred is not None:
                    return inferred
            return None
        if isinstance(x, dict):
            for item in x.values():
                inferred = self._infer_batch_size(item)
                if inferred is not None:
                    return inferred
            return None
        shape = getattr(x, "shape", None)
        if shape is None or len(shape) == 0:
            return None
        if shape[0] is None:
            return None
        return int(shape[0])

    def _prepare_validation_data(self, validation_data: Any) -> Any:
        if validation_data is None:
            return None
        if not isinstance(validation_data, (list, tuple)):
            return validation_data
        if len(validation_data) == 2:
            x_val, y_val = validation_data
            return (x_val, y_val)
        if len(validation_data) == 3:
            x_val, y_val, val_weights = validation_data
            return (x_val, y_val, val_weights)
        return validation_data

    def fit(self, x: Any = None, y: Any = None, batch_size: int | None = None, **kwargs: Any):
        if self.full_batch_training and batch_size is None:
            batch_size = self._infer_batch_size(x)
        if self.full_batch_training:
            kwargs["shuffle"] = False
            validation_data = self._prepare_validation_data(kwargs.get("validation_data"))
            if validation_data is not None:
                kwargs["validation_data"] = validation_data
            if batch_size is not None and "validation_batch_size" not in kwargs:
                kwargs["validation_batch_size"] = batch_size
        return super().fit(x=x, y=y, batch_size=batch_size, **kwargs)

    def evaluate(self, x: Any = None, y: Any = None, batch_size: int | None = None, **kwargs: Any):
        if self.full_batch_training and batch_size is None:
            batch_size = self._infer_batch_size(x)
        return super().evaluate(x=x, y=y, batch_size=batch_size, **kwargs)

    def predict(self, x: Any, batch_size: int | None = None, **kwargs: Any):
        if self.full_batch_training and batch_size is None:
            batch_size = self._infer_batch_size(x)
        return super().predict(x=x, batch_size=batch_size, **kwargs)

