def aggregate_neighbor_features(
    features: sp.spmatrix | np.ndarray,
    graph: nx.Graph | nx.DiGraph | dict[int, Sequence[int]] | sp.spmatrix | np.ndarray,
    strategy: str = "mean",
    include_self: bool = False,
    directed: bool = False,
) -> np.ndarray:
    dense_features = sparse_to_dense(features)

    if sp.issparse(graph) or isinstance(graph, np.ndarray):
        create_using = nx.DiGraph() if directed else nx.Graph()
        graph_obj = (
            nx.from_scipy_sparse_array(graph, create_using=create_using)
            if sp.issparse(graph)
            else nx.from_numpy_array(graph, create_using=create_using)
        )
    elif isinstance(graph, dict):
        graph_obj = nx.from_dict_of_lists(graph, create_using=nx.DiGraph() if directed else nx.Graph())
    else:
        graph_obj = graph

    neighbor_indices = []
    for node in graph_obj.nodes():
        neighbors = list(graph_obj.neighbors(node))
        if include_self:
            neighbors.append(node)
        if not neighbors:
            neighbors = [node]
        neighbor_indices.append(neighbors)

    max_neighbors = max(len(neighbors) for neighbors in neighbor_indices)
    padded = []
    for node, neighbors in enumerate(neighbor_indices):
        pad_value = neighbors[-1] if neighbors else node
        padded.append(neighbors + [pad_value] * (max_neighbors - len(neighbors)))
    return aggregate_features(dense_features, np.asarray(padded, dtype=np.int64), strategy=strategy)

